const werkRedactieRegels = [{"date":"27/05","head":"een regeling treffen","before":{"examples":[{"nl":"We moeten een regeling treffen voor de huurachterstand.","tr":"Kira borcunun gecikmesi için bir düzenleme yapmalıyız."},{"nl":"Ik heb een betalingsregeling getroffen met de schuldeiser.","tr":"Alacaklıyla bir ödeme planı yaptım."},{"nl":"Kunnen we een regeling treffen zodat hij zijn rekeningen kan betalen?","tr":"Faturalarını ödeyebilmesi için bir düzenleme yapabilir miyiz?"}]},"after":{"examples":[{"nl":"We moeten een regeling treffen voor de huurachterstand.","tr":"Biriken kira borcu için bir anlaşma yapmamız gerekiyor."},{"nl":"Ik heb een betalingsregeling getroffen met de schuldeiser.","tr":"Alacaklıyla bir ödeme planı yaptım."},{"nl":"Kunnen we een regeling treffen zodat hij zijn rekeningen kan betalen?","tr":"Faturalarını ödeyebilmesi için bir düzenleme yapabilir miyiz?"}]}},{"date":"27/05","head":"Ik kan je aanmelden.","before":{"turkish":"Seni kaydedebilirim / başvurunuzu yapabilirim.","note":"'Aanmelden' = kayıt yaptırmak, başvuru yapmak. Sosyal hizmetlerde bir programa veya kuruma kayıt için çok kullanılır.","legal":"Türk hukukunda 'başvuru yapmak' veya 'müracaat'. İdari hukuk bağlamında önemli adım — aanmelding olmadan hizmet akışı başlamaz.","isLegal":true,"examples":[{"nl":"Ik kan je aanmelden voor de schuldhulpverlening.","tr":"Seni borç yardım hizmetine kaydedebilirim."},{"nl":"Wil je dat ik je aanmeld bij de voedselbank?","tr":"Seni gıda bankasına kaydettirmemi ister misin?"},{"nl":"Ik kan je aanmelden, maar je hebt wel een DigiD nodig.","tr":"Seni kayıt edebilirim ama DigiD'e ihtiyacın var."}]},"after":{"turkish":"İstersen senin adına başvuru yapabilirim.","note":"Je ve jou samimi hitap biçimleridir. Resmî hitapta “Ik kan u aanmelden” denir.","legal":null,"isLegal":false,"examples":[{"nl":"Wil je dat ik je aanmeld?","tr":"Senin adına başvuru yapmamı ister misin?"},{"nl":"Zullen we samen kijken wat je nodig hebt voor de aanmelding?","tr":"Başvuru için neye ihtiyacın olduğuna birlikte bakalım mı?"}]}},{"date":"13/05","head":"zienswijze","before":{"turkish":"görüş / bakış açısı / resmi itiraz görüşü","note":"Hem günlük dilde 'bakış açısı' hem de idare hukukunda resmi bir terim: bir plan veya besluit hakkında yazılı görüş bildirme. Bezwaar'dan önce gelen daha erken bir katılım biçimi.","legal":"Türk idare hukukunda 'görüş bildirme' veya 'itiraz'. Hollanda'da Wet ruimtelijke ordening ve Awb çerçevesinde zienswijze, een besluit kesinleşmeden önce sunulan resmi görüştür. Bezwaar'dan farklıdır: zienswijze een ontwerp-besluit'e karşı sunulur.","examples":[{"nl":"U kunt een zienswijze indienen tegen het bestemmingsplan.","tr":"İmar planına karşı resmi görüş bildirebilirsiniz."},{"nl":"Wat is uw zienswijze op dit voorstel?","tr":"Bu teklife ilişkin görüşünüz nedir?"},{"nl":"De gemeente heeft alle zienswijzen bekeken voor het definitieve besluit.","tr":"Belediye, kesin karardan önce tüm görüşleri inceledi."}]},"after":{"turkish":"görüş / bir plan veya öneri hakkında bildirilen görüş","note":"Bir yazıda zienswijze sözcüğünü gördüğünde hangi plan veya önerinin kastedildiğine bak.","legal":null,"examples":[{"nl":"In de brief staat het woord ‘zienswijze’. Wat betekent dat?","tr":"Mektupta “zienswijze” sözcüğü geçiyor. Bu ne demek?"},{"nl":"Wat is uw zienswijze op dit voorstel?","tr":"Bu öneri hakkındaki görüşünüz nedir?"}]}},{"date":"21/05","head":"warme overdracht","before":{"turkish":"sıcak devir / kişisel geçiş desteği","note":"Sosyal hizmetlerde çok önemli bir kavram. Bir müşteriyi sadece dosya devretmek değil, yeni yardımcıya bizzat tanıtmak / köprü kurmak. 'Warm' = kişisel, bağlantılı; karşıtı 'koude overdracht' = sadece belge devri.","legal":"Türk sosyal hizmet terminolojisinde 'vaka transferi' veya 'kişisel yönlendirme'. Wmo ve Jeugdwet'te continuïteit van zorg ilkesiyle ilişkilidir.","isLegal":true,"examples":[{"nl":"We doen een warme overdracht zodat de cliënt niet opnieuw alles hoeft te vertellen.","tr":"Müşterinin her şeyi yeniden anlatmak zorunda kalmaması için sıcak devir yapıyoruz."},{"nl":"Ik stel je voor aan mijn collega, dit is een warme overdracht.","tr":"Seni meslektaşıma tanıştırıyorum — bu bir sıcak devirdir."},{"nl":"Een warme overdracht verhoogt de kans dat de cliënt de hulp ook echt oppakt.","tr":"Sıcak devir, müşterinin yardımı gerçekten devam ettirme ihtimalini artırır."}]},"after":{"turkish":"danışanı yeni uzmana bizzat tanıştırarak yönlendirme","note":"Ekip içinde “warme overdracht” denebilir. Danışana ne yapmayı önerdiğini somut bir cümleyle anlat.","legal":null,"isLegal":false,"examples":[{"nl":"Wilt u dat ik u aan mijn collega voorstel?","tr":"Sizi meslektaşımla tanıştırmamı ister misiniz?"},{"nl":"We hebben met haar besproken wat ze bij de warme overdracht wil vertellen.","tr":"Yeni uzmanla tanışırken neleri anlatmak istediğini kendisiyle konuştuk."}]}},{"date":"08/06","head":"Ben je geopereerd aan je maag?","before":{"turkish":"Midenizden ameliyat oldunuz mu?","note":"Intake veya gezondheidsanamnese sırasında sorulan bir soru. Sosyal raadsman olarak sağlık durumunu anlamak, doğru yardım veya uitkering hakkı için gerekli olabilir.","examples":[{"nl":"Ben je geopereerd aan je maag? Dat kan invloed hebben op je uitkering.","tr":"Midenizden ameliyat oldunuz mu? Bu yardım ödemelerinizi etkileyebilir."},{"nl":"Is er ooit een operatie geweest aan je maag of darmen?","tr":"Mide veya bağırsaklarınızda daha önce bir ameliyat oldu mu?"},{"nl":"Voor de WIA-aanvraag is het belangrijk om medische ingrepen te vermelden.","tr":"WIA başvurusu için tıbbi müdahaleleri belirtmek önemli."}]},"after":{"turkish":"Midenden ameliyat oldun mu?","note":"Je samimi hitaptır. Sağlıkla ilgili bir konuşmada duyulabilecek bir sorudur.","examples":[{"nl":"Ik ben aan mijn maag geopereerd.","tr":"Midemden ameliyat oldum."},{"nl":"U vertelde dat u geopereerd bent. Waarmee kan ik u vandaag helpen?","tr":"Ameliyat olduğunuzu söylediniz. Bugün size hangi konuda yardımcı olabilirim?"}]}},{"date":"STAJ","head":"dikke bankrekening","before":{"examples":[{"nl":"Hij heeft een dikke bankrekening, hij heeft geen recht op toeslagen.","tr":"Kabarık bir banka hesabı var, toeslag hakkı bulunmuyor."},{"nl":"Niet iedereen met een dikke bankrekening is ook gelukkig.","tr":"Kabarık banka hesabı olan herkes mutlu değildir."},{"nl":"Ze controleren of je een dikke bankrekening hebt bij de aanvraag.","tr":"Başvuruda kabarık bir banka hesabın olup olmadığını kontrol ediyorlar."}]},"after":{"examples":[{"nl":"Een dikke bankrekening is een informele manier om te zeggen dat iemand veel geld heeft.","tr":"Dikke bankrekening, birinin çok parası olduğunu söylemenin samimi bir yoludur."},{"nl":"Welke informatie heeft u over uw inkomsten en uitgaven?","tr":"Gelir ve giderleriniz hakkında elinizde hangi bilgiler var?"}]}},{"date":"STAJ","head":"pro-forma","before":{"dutch":"pro-forma","turkish":"şekli / biçimsel / formalite gereği","note":"Latince kökenli. 'Pro forma' = sadece şekli olarak, görünüşte. Hukuki süreçlerde örn. pro-forma zitting = süreyi korumak için yapılan biçimsel duruşma. İçeriği olmayan ama süreci başlatan işlem.","legal":"Türk hukukunda 'usule ilişkin' veya 'şekli başvuru'. Pro-forma bezwaar: süre kaybını önlemek için içerik tamamlanmadan yapılan itiraz. Türk idare hukukunda 'ihtirazi kayıt koyarak başvuru' ile benzer işlev.","etymology":"Latince `pro forma` = \"biçim için\". Roma hukukundan Hollanda hukuk diline geçmiştir.","uitleg":"Iets doen om de vorm te bewaren, nog zonder inhoud.","examples":[{"nl":"Dit is een pro-forma melding, puur om de termijn te bewaken.","tr":"Bu sadece süreyi korumak için yapılmış biçimsel bir bildirim."},{"nl":"De pro-forma zitting is gepland voor volgende maand.","tr":"Biçimsel duruşma gelecek ay planlandı."},{"nl":"We dienen pro forma bezwaar in totdat we alle stukken hebben.","tr":"Tüm belgeleri alana kadar şeklen itiraz sunuyoruz."}]},"after":{"dutch":"pro forma","turkish":"usulen / şeklen","note":"Anlamını mektuptaki kelime grubuna göre kontrol et. “Een pro-formazitting” bir duruşma türüdür.","legal":null,"etymology":null,"uitleg":"Een formele stap. Uit de context blijkt om wat voor stap het gaat.","examples":[{"nl":"In de brief wordt een pro-formazitting genoemd.","tr":"Mektupta, davanın esasının ele alınmayacağı bir duruşmadan söz ediliyor."},{"nl":"Wat betekent ‘pro forma’ in deze brief?","tr":"Bu mektupta “pro forma” ne anlama geliyor?"}]}},{"date":"STAJ","head":"in dit kader","before":{"examples":[{"nl":"In dit kader is het belangrijk om de termijnen te bewaken.","tr":"Bu çerçevede süreleri takip etmek önemlidir."},{"nl":"In dit kader verwijzen wij naar artikel 6 van de wet.","tr":"Bu bağlamda yasanın 6. maddesine atıfta bulunuyoruz."},{"nl":"In dit kader heeft de cliënt recht op ondersteuning.","tr":"Bu çerçevede müşterinin desteğe hakkı bulunmaktadır."}]},"after":{"examples":[{"nl":"In dit kader is het belangrijk om de termijnen te bewaken.","tr":"Bu çerçevede süreleri takip etmek önemlidir."},{"nl":"In dit kader verwijzen wij naar artikel 6 van de wet.","tr":"Bu bağlamda yasanın 6. maddesine atıfta bulunuyoruz."},{"nl":"In dit kader wil de cliënt weten welke ondersteuning mogelijk is.","tr":"Danışan bu bağlamda hangi desteğin mümkün olduğunu öğrenmek istiyor."}]}},{"date":"STAJ","head":"re-integreren","before":{"note":"Sosyal hizmetlerde çok kullanılır. Özellikle WIA/WW kapsamında işten uzak kalan kişinin iş hayatına geri dönüş sürecini ifade eder. 'Re-integratietraject' = bu sürecin planı.","legal":"Türk hukukunda 'mesleki rehabilitasyon' veya 'işe yeniden uyum'. Hollanda'da Wet WIA md. 25 kapsamında werkgever reïntegratieplicht (işveren yükümlülüğü) taşır. Spoor 1 (kendi işverene dönüş) ve Spoor 2 (başka işverene geçiş) ayrımı önemlidir.","isLegal":true},"after":{"note":"İsim biçimi “re-integratie”, fiil biçimi “re-integreren”.","legal":null,"isLegal":false}},{"date":"STAJ","head":"opbouwen","before":{"examples":[{"nl":"Hij heeft jaren WW opgebouwd en heeft nu recht op een uitkering.","tr":"Yıllarca WW hakkı biriktirdi ve şimdi ödenek alma hakkı var."},{"nl":"We proberen een vertrouwensrelatie op te bouwen met de cliënt.","tr":"Müşteriyle güven ilişkisi oluşturmaya çalışıyoruz."},{"nl":"Ze heeft geen pensioen opgebouwd tijdens haar huwelijk.","tr":"Evliliği sırasında emeklilik birikimi oluşturmamış."}]},"after":{"examples":[{"nl":"Hij wil weten welke WW-rechten hij tijdens zijn werk heeft opgebouwd.","tr":"Çalıştığı süre içinde hangi işsizlik ödeneği haklarını biriktirdiğini öğrenmek istiyor."},{"nl":"We proberen een vertrouwensrelatie op te bouwen met de cliënt.","tr":"Müşteriyle güven ilişkisi oluşturmaya çalışıyoruz."},{"nl":"Ze heeft geen pensioen opgebouwd tijdens haar huwelijk.","tr":"Evliliği sırasında emeklilik birikimi oluşturmamış."}]}},{"date":"STAJ","head":"in aanmerking (komen)","before":{"dutch":"in aanmerking (komen)","turkish":"hak kazanmak / dikkate alınmak / uygun olmak","note":"'In aanmerking komen voor iets' = bir şeye hak kazanmak, uygun olmak. Sosyal hizmetlerde en çok kullanılan ifadelerden biri. 'In aanmerking nemen' = dikkate almak.","legal":"Türk hukukunda 'hak kazanmak' veya 'yararlanmak'. Bestuursrechtelijk: 'recht hebben op' ile eş anlamlı kullanılır ama 'in aanmerking komen' daha geniş — hem hak hem uygunluk kriterini kapsar.","examples":[{"nl":"Komt hij in aanmerking voor huurtoeslag?","tr":"Kira yardımı almaya hak kazanıyor mu?"},{"nl":"U komt niet in aanmerking voor deze regeling vanwege uw inkomen.","tr":"Geliriniz nedeniyle bu düzenlemeye uygun değilsiniz."},{"nl":"We nemen alle omstandigheden in aanmerking bij de beoordeling.","tr":"Değerlendirmede tüm koşulları dikkate alıyoruz."}]},"after":{"dutch":"in aanmerking komen voor","turkish":"bir şey için uygun olmak / koşulları karşılamak","note":"Ardından “voor” ve başvurulan yardım ya da hizmet gelir.","legal":null,"examples":[{"nl":"Ik wil weten of ik voor deze regeling in aanmerking kom.","tr":"Bu düzenlemeden yararlanma koşullarını karşılayıp karşılamadığımı öğrenmek istiyorum."}]}},{"date":"STAJ","head":"woonachtig","before":{"examples":[{"nl":"De cliënt is woonachtig in de gemeente Zuidplas.","tr":"Müşteri Zuidplas belediyesinde ikamet etmektedir."},{"nl":"U dient woonachtig te zijn in Nederland om in aanmerking te komen.","tr":"Hak kazanabilmek için Hollanda'da ikamet etmeniz gerekmektedir."},{"nl":"Bent u al langer dan zes maanden woonachtig op dit adres?","tr":"Bu adreste altı aydan uzun süredir ikamet ediyor musunuz?"}]},"after":{"examples":[{"nl":"De cliënt is woonachtig in de gemeente Zuidplas.","tr":"Müşteri Zuidplas belediyesinde ikamet etmektedir."},{"nl":"Op het formulier wordt gevraagd of u in Nederland woonachtig bent.","tr":"Formda Hollanda’da ikamet edip etmediğiniz soruluyor."},{"nl":"Bent u al langer dan zes maanden woonachtig op dit adres?","tr":"Bu adreste altı aydan uzun süredir ikamet ediyor musunuz?"}]}},{"date":"STAJ","head":"zitting","before":{"note":"Mahkeme veya bestuursrechtelijk beroep sürecindeki resmi oturum. 'Zitting bijwonen' = duruşmaya katılmak. 'Pro-forma zitting' = biçimsel oturum (içerik yok, süre korunuyor).","legal":"Türk hukukunda 'duruşma'. Hollanda'da bestuursrecht beroepsprocedure sırasında rechtbank veya CBb/ABRvS zitting yapar. Kantonrechter (huurzaken, schulden) ve voorzieningenrechter (kort geding) de zitting houdt.","examples":[{"nl":"De zitting bij de rechtbank is gepland op 15 juni.","tr":"Mahkemedeki duruşma 15 Haziran'a planlandı."},{"nl":"U hoeft niet aanwezig te zijn bij de pro-forma zitting.","tr":"Biçimsel duruşmada bulunmanız gerekmez."},{"nl":"Na de zitting ontvangt u schriftelijk de uitspraak.","tr":"Duruşmanın ardından kararı yazılı olarak alacaksınız."}]},"after":{"note":"Zitting bir duruşma veya oturumdur. Çağrı yazısından hangi duruşmanın kastedildiğine bak.","legal":null,"examples":[{"nl":"De zitting bij de rechtbank is gepland op 15 juni.","tr":"Mahkemedeki duruşma 15 Haziran'a planlandı."},{"nl":"Staat er in de oproep of u bij de pro-formazitting aanwezig moet zijn?","tr":"Çağrı yazısında bu duruşmaya katılmanız gerekip gerekmediği yazıyor mu?"},{"nl":"Na de zitting ontvangt u schriftelijk de uitspraak.","tr":"Duruşmanın ardından kararı yazılı olarak alacaksınız."}]}},{"date":"STAJ","head":"degene","before":{"examples":[{"nl":"Degene die de aanvraag heeft ingediend, moet aanwezig zijn.","tr":"Başvuruyu yapan kişinin hazır bulunması gerekir."},{"nl":"Dit geldt voor degene die woonachtig is in de gemeente.","tr":"Bu, belediyede ikamet eden kişi için geçerlidir."},{"nl":"U bent degene die verantwoordelijk is voor de betaling.","tr":"Ödemenin sorumluluğunu taşıyan kişi sizsiniz."}]},"after":{"examples":[{"nl":"Staat in de uitnodiging dat degene die de aanvraag heeft ingediend, erbij moet zijn?","tr":"Davette başvuruyu yapan kişinin katılması gerektiği yazıyor mu?"},{"nl":"Dit geldt voor degene die woonachtig is in de gemeente.","tr":"Bu, belediyede ikamet eden kişi için geçerlidir."},{"nl":"U bent degene die verantwoordelijk is voor de betaling.","tr":"Ödemenin sorumluluğunu taşıyan kişi sizsiniz."}]}},{"date":"STAJ","head":"afloop","before":{"examples":[{"nl":"Na afloop van de bezwaarprocedure ontvangt u een beslissing.","tr":"İtiraz sürecinin sonunda bir karar alacaksınız."},{"nl":"Wat was de afloop van het gesprek met de gemeente?","tr":"Belediyeyle görüşmenin sonucu ne oldu?"},{"nl":"De termijn loopt binnenkort af, actie is vereist.","tr":"Süre yakında dolacak, eylem gerekiyor."}]},"after":{"examples":[{"nl":"Na afloop van de bezwaarprocedure ontvangt u een beslissing.","tr":"İtiraz sürecinin sonunda bir karar alacaksınız."},{"nl":"Wat was de afloop van het gesprek met de gemeente?","tr":"Belediyeyle görüşmenin sonucu ne oldu?"},{"nl":"Volgens de brief loopt de termijn binnenkort af. Welke datum staat er precies?","tr":"Mektuba göre süre yakında doluyor. Tam olarak hangi tarih yazıyor?"}]}},{"date":"STAJ","head":"beoordelen","before":{"examples":[{"nl":"De gemeente beoordeelt de aanvraag binnen acht weken.","tr":"Belediye başvuruyu sekiz hafta içinde değerlendirir."},{"nl":"Wij beoordelen uw situatie op basis van de ingediende stukken.","tr":"Durumunuzu sunulan belgeler temelinde değerlendiriyoruz."},{"nl":"De rechter beoordeelt of er sprake is van onrechtmatige daad.","tr":"Hâkim haksız fiilin söz konusu olup olmadığını değerlendirir."}],"legal":"Türk hukukunda 'değerlendirmek' veya 'takdir etmek'. Bestuursrechtelijk: bestuursorgaan beoordeelt de aanvraag o.b.v. de wet. Marginale toetsing (sınırlı denetim) vs. volledige toetsing (tam denetim) ayrımı önemli."},"after":{"examples":[{"nl":"Staat in de brief wanneer de gemeente uw aanvraag beoordeelt?","tr":"Mektupta belediyenin başvurunuzu ne zaman değerlendireceği yazıyor mu?"},{"nl":"Wij beoordelen uw situatie op basis van de ingediende stukken.","tr":"Durumunuzu sunulan belgeler temelinde değerlendiriyoruz."},{"nl":"De rechter beoordeelt of er sprake is van onrechtmatige daad.","tr":"Hâkim haksız fiilin söz konusu olup olmadığını değerlendirir."}],"legal":null}},{"date":"STAJ","head":"acceptgiro","before":{"examples":[{"nl":"Er is een acceptgiro meegestuurd met de huurrekening.","tr":"Kira faturasıyla birlikte bir ödeme formu gönderilmiş."},{"nl":"Hij weet niet hoe hij de acceptgiro moet betalen.","tr":"Ödeme formunu nasıl ödeyeceğini bilmiyor."},{"nl":"Je kunt de acceptgiro inleveren bij de bank of online betalen.","tr":"Ödeme formunu bankaya teslim edebilir ya da online ödeyebilirsin."}],"turkish":"ödeme fişi / ödeme formu / giro makbuzu","note":"Eski usul kâğıt ödeme formu. Artık dijital ortamda da 'acceptgiro' denilir. Fatura veya borç bildirimiyle birlikte gelen, bankaya götürülerek ödeme yapılabilen belge. Dijital bankacılığa geçmeyen yaşlı müşterilerde sık karşılaşılır."},"after":{"examples":[{"nl":"Bij een oude huurrekening vond ik een acceptgiro.","tr":"Eski bir kira faturasıyla birlikte bir ödeme formu buldum."},{"nl":"Hij weet niet hoe hij de acceptgiro moet betalen.","tr":"Ödeme formunu nasıl ödeyeceğini bilmiyor."},{"nl":"Je kunt de acceptgiro inleveren bij de bank of online betalen.","tr":"Ödeme formunu bankaya teslim edebilir ya da online ödeyebilirsin."}],"turkish":"eskiden kullanılan basılı ödeme formu","note":"Eski evraklarda ve geçmişte yapılan ödemeler anlatılırken karşılaşabileceğin bir sözcük."}},{"date":"STAJ","head":"immers","before":{"examples":[{"nl":"Hij heeft recht op ondersteuning, hij is immers woonachtig in de gemeente.","tr":"Nitekim belediyede ikamet ettiğinden, desteğe hak kazanmaktadır."},{"nl":"De termijn is verstreken, de bezwaarschrift is immers te laat ingediend.","tr":"Süre dolmuştu; zira itiraz dilekçesi geç sunulmuştu."},{"nl":"U bent immers al klant bij ons.","tr":"Bilindiği üzere zaten bizim müşterimizsiniz."}]},"after":{"examples":[{"nl":"Ik ken de brief. We hebben hem immers gisteren samen gelezen.","tr":"Mektubu biliyorum. Ne de olsa dün birlikte okuduk."},{"nl":"Een nieuwe afspraak is handig. De vorige afspraak ging immers niet door.","tr":"Yeni bir randevu iyi olur. Çünkü önceki randevu gerçekleşmedi."}]}},{"date":"STAJ","head":"bekeuring","before":{"note":"Polis tarafından verilen ceza belgesi. Mulderboete'den fark: bekeuring daha geniş kapsamlı, Mulderboete ise idari sistem kapsamındaki trafik ihlallerine özel.","legal":"Türk hukukunda 'trafik cezası' veya 'idari para cezası'. CJIB bağlamında sociaal raadsman için önemli — ödenmezse verhoogd wordt en invordering volgt.","examples":[{"nl":"Hij heeft een bekeuring gekregen wegens te hard rijden.","tr":"Hız ihlali nedeniyle trafik cezası aldı."},{"nl":"De bekeuring moet binnen zes weken betaald worden.","tr":"Trafik cezası altı hafta içinde ödenmelidir."},{"nl":"Je kunt bezwaar maken tegen een bekeuring.","tr":"Bir trafik cezasına itiraz edebilirsin."}]},"after":{"note":"Özellikle trafik bağlamında duyabileceğin “para cezası” sözcüğü.","legal":null,"examples":[{"nl":"Ik heb een bekeuring gekregen.","tr":"Para cezası aldım."},{"nl":"Welke betaaldatum staat er in de brief over de bekeuring?","tr":"Cezayla ilgili mektupta hangi ödeme tarihi yazıyor?"}]}},{"date":"STAJ","head":"Wat staat daar in?","before":{"dutch":"Wat staat daar in?","turkish":"Orada ne yazıyor? / İçinde ne var?","examples":[{"nl":"Wat staat daar in? Ik begrijp de brief niet.","tr":"Orada ne yazıyor? Mektubu anlamıyorum."},{"nl":"Wat staat er precies in dat besluit?","tr":"O kararda tam olarak ne yazıyor?"},{"nl":"Kunt u mij uitleggen wat er in dit formulier staat?","tr":"Bu formda ne yazdığını açıklar mısınız?"}]},"after":{"dutch":"Wat staat daarin?","turkish":"İçinde ne yazıyor?","examples":[{"nl":"Wat staat daarin? Ik begrijp de brief niet.","tr":"İçinde ne yazıyor? Mektubu anlamıyorum."},{"nl":"Zullen we samen kijken wat erin staat?","tr":"İçinde ne yazdığına birlikte bakalım mı?"}]}},{"date":"STAJ","head":"seksueel misbruik","before":{"turkish":"cinsel istismar / cinsel taciz","note":"'Misbruik' = kötüye kullanma, istismar. 'Seksueel misbruik' = cinsel istismar, özellikle güç ilişkisi bağlamında (çocuklar, bağımlı bireyler). Sosyal hizmetlerde bildirme yükümlülüğü doğurabilir.","legal":"Türk Ceza Kanunu md. 102-105 cinsel suçlar. Hollanda WvSr md. 242-249 verkrachting en ontucht. Meldcode Huiselijk Geweld en Kindermishandeling kapsamında sociaal werkers meldplicht taşır.","examples":[{"nl":"Er zijn vermoedens van seksueel misbruik, we melden dit bij Veilig Thuis.","tr":"Cinsel istismar şüphesi var, bunu Veilig Thuis'a bildiriyoruz."},{"nl":"Slachtoffers van seksueel misbruik hebben recht op professionele hulp.","tr":"Cinsel istismar mağdurlarının profesyonel yardıma hakkı var."},{"nl":"Seksueel misbruik is strafbaar en dient gemeld te worden.","tr":"Cinsel istismar suçtur ve bildirilmesi gerekir."}]},"after":{"turkish":"cinsel istismar","note":"Misbruik “istismar” demektir. Seksuele intimidatie için Türkçede “cinsel taciz” kullanılır.","legal":null,"examples":[{"nl":"In de brief staat de term ‘seksueel misbruik’.","tr":"Mektupta “cinsel istismar” ifadesi geçiyor."}]}},{"date":"STAJ","head":"seksuele intimidatie","before":{"turkish":"cinsel taciz / cinsel yıldırma","note":"'Misbruik'ten fark: intimidatie daha geniş kapsamlı, fiziksel temas olmaksızın da olabilir (sözlü, nonverbaal). İşyerinde ve özel hayatta ayrı hukuki düzenlemeler.","legal":"Türk hukukunda 'cinsel taciz' — TCK md. 105. Hollanda: Arbowet md. 3 (werkgever verplichtingen), WvSr md. 239, 246. Gelijke behandelingswetgeving ook van toepassing.","examples":[{"nl":"Seksuele intimidatie op de werkvloer is verboden.","tr":"İşyerinde cinsel taciz yasaktır."},{"nl":"Ze heeft aangifte gedaan van seksuele intimidatie.","tr":"Cinsel taciz için suç duyurusunda bulundu."},{"nl":"De werkgever is verplicht om seksuele intimidatie te voorkomen.","tr":"İşveren cinsel tacizi önlemek zorundadır."}]},"after":{"turkish":"cinsel taciz","note":"İş yerinde istenmeyen cinsel söz, ilgi veya davranış anlatılırken bu terimi duyabilirsin.","legal":null,"examples":[{"nl":"Ik wil met iemand praten over seksuele intimidatie op mijn werk.","tr":"İş yerinde yaşadığım cinsel taciz hakkında biriyle konuşmak istiyorum."}]}},{"date":"STAJ","head":"Dat is niet het geval.","before":{"examples":[{"nl":"U denkt dat hij recht heeft, maar dat is niet het geval.","tr":"Hakkı olduğunu düşünüyorsunuz, ama durum böyle değil."},{"nl":"Er zou sprake zijn van fraude, maar dat is niet het geval.","tr":"Dolandırıcılık söz konusu olduğu iddia edildi, ama bu böyle değil."},{"nl":"Dat is niet het geval; de termijn is nog niet verstreken.","tr":"Durum böyle değil; süre henüz dolmadı."}]},"after":{"examples":[{"nl":"U dacht dat de brief al verstuurd was, maar dat is niet het geval.","tr":"Mektubun gönderildiğini düşünüyordunuz ama henüz gönderilmedi."},{"nl":"Er zou sprake zijn van fraude, maar dat is niet het geval.","tr":"Dolandırıcılık söz konusu olduğu iddia edildi, ama bu böyle değil."},{"nl":"Dat is niet het geval; de termijn is nog niet verstreken.","tr":"Durum böyle değil; süre henüz dolmadı."}]}},{"date":"15/06","head":"Daar hebben we een inloopuur voor.","before":{"turkish":"Bunun için walk-in saatimiz var. / Bunun için serbest başvuru saatimiz var.","note":"'Inloopuur' = önceden randevu almadan gidilen serbest danışma saati. ZO! gibi kurumların temel hizmetlerinden biri. 'Inlopen' = randevusuz girmek.","examples":[{"nl":"U hoeft geen afspraak te maken. Daar hebben we inloopuur voor.","tr":"Randevu almanıza gerek yok. Bunun için serbest başvuru saatimiz var."},{"nl":"Het inloopuur is elke dinsdag van 9 tot 12 uur.","tr":"Serbest başvuru saati her salı 9'dan 12'ye kadar."},{"nl":"Voor kleine vragen kunt u terecht tijdens het inloopuur.","tr":"Küçük sorular için serbest başvuru saatimize gelebilirsiniz."}]},"after":{"turkish":"Bunun için randevusuz danışma saatimiz var.","note":"Inloopuur, randevu almadan gelinebilen danışma saatidir.","examples":[{"nl":"Daar hebben we een inloopuur voor. Zal ik kijken wanneer het is?","tr":"Bunun için randevusuz danışma saatimiz var. Ne zaman olduğuna bakayım mı?"}]}},{"date":"15/06","head":"Ik ben van Stichting ZO!","before":{"etymology":"Yapı: `van` (den) + `[organisatie]` + `ben ik` (benim) — kendini kurum adına tanıtma kalıbı.","turkish":"Ben Stichting ZO!'dan geliyorum! / Stichting ZO! adına ben buradayım.","examples":[{"nl":"Goedemiddag, ik ben van Stichting ZO! — mijn naam is Yasin.","tr":"İyi günler, ben Stichting ZO!'dan Yasin."},{"nl":"Ik ben van Stichting ZO!, ik bel namens uw cliënt.","tr":"Ben Stichting ZO!'dan arıyorum, müşteriniz adına."},{"nl":"U spreekt met Stichting ZO! — waarmee kan ik u helpen?","tr":"Stichting ZO! ile görüşüyorsunuz — size nasıl yardımcı olabilirim?"}]},"after":{"etymology":null,"turkish":"Ben Stichting ZO!’danım.","examples":[{"nl":"Goedemiddag, u spreekt met Yasin van Stichting ZO!","tr":"İyi günler, ben Stichting ZO!’dan Yasin."},{"nl":"Ik ben van Stichting ZO! Waarmee kan ik u helpen?","tr":"Ben Stichting ZO!’danım. Size nasıl yardımcı olabilirim?"}]}},{"date":"17/06","head":"Zijn we zo duidelijk?","before":{"dutch":"Zijn we zo duidelijk?","turkish":"Bu şekilde anlaşıldık mı? / Bu kadar açık mı?","note":"Bir açıklama yaptıktan sonra anlaşılıp anlaşılmadığını teyit etmek için sorulan kısa soru. 'Is dit duidelijk?' ile benzer ama 'zo' ekiyle az daha gayri resmi.","examples":[{"nl":"U moet de stukken voor vrijdag inleveren. Zijn we zo duidelijk?","tr":"Belgeleri Cuma'dan önce teslim etmeniz gerekiyor. Bu şekilde anlaşıldık mı?"},{"nl":"Zijn we zo duidelijk over de vervolgstappen?","tr":"Sonraki adımlar konusunda bu kadar açık mıyız?"},{"nl":"Ik wil zeker weten: zijn we zo duidelijk?","tr":"Emin olmak istiyorum: bu şekilde anlaşıldık mı?"}]},"after":{"dutch":"Heb ik het zo duidelijk uitgelegd?","turkish":"Böyle anlaşılır açıklayabildim mi?","note":"Açıklamanın anlaşılır olup olmadığını sorar. Kişiye kendi sorusunu sorması için de alan açabilirsin.","examples":[{"nl":"Heb ik het zo duidelijk uitgelegd, of zal ik een voorbeeld geven?","tr":"Böyle anlaşılır açıklayabildim mi, yoksa örnek vereyim mi?"},{"nl":"Welke vragen heeft u nog over de volgende stap?","tr":"Bir sonraki adımla ilgili başka hangi sorularınız var?"}]}},{"date":"17/06","head":"vermelden","before":{"examples":[{"nl":"Vermeld in de brief uw dossiernummer.","tr":"Mektupta dosya numaranızı belirtin."},{"nl":"Het is belangrijk om alle inkomsten te vermelden.","tr":"Tüm gelirleri belirtmek önemlidir."},{"nl":"Heeft u dit al vermeld in uw aanvraag?","tr":"Bunu başvurunuzda zaten belirttiniz mi?"}]},"after":{"examples":[{"nl":"Vermeld in de brief uw dossiernummer.","tr":"Mektupta dosya numaranızı belirtin."},{"nl":"Welke inkomsten moet u op dit formulier vermelden?","tr":"Bu formda hangi gelirleri belirtmeniz gerekiyor?"},{"nl":"Heeft u dit al vermeld in uw aanvraag?","tr":"Bunu başvurunuzda zaten belirttiniz mi?"}]}},{"date":"17/06","head":"bemenst","before":{"turkish":"personel ile donatılmış / görevliyle dolu","examples":[{"nl":"Het inloopuur is altijd bemenst door minimaal twee collega's.","tr":"Serbest başvuru saatinde her zaman en az iki meslektaş görevlidir."},{"nl":"De balie is op dit moment niet bemenst.","tr":"Resepsiyon şu anda görevsiz."},{"nl":"We hebben extra collega's nodig om de telefoonlijn goed te bemensen.","tr":"Telefon hattını düzgün şekilde personelle donatmak için ekstra meslektaşa ihtiyacımız var."}]},"after":{"turkish":"görevli bulunan / başında personel olan","examples":[{"nl":"Is de balie vanmiddag bemenst?","tr":"Bugün öğleden sonra danışmada görevli var mı?"},{"nl":"Wie bemenst vandaag de telefoon?","tr":"Bugün telefonlara kim bakıyor?"}]}},{"date":"08/07","head":"Wie mag de laatste geweest zijn?","before":{"dutch":"Wie mag de laatste geweest zijn?","turkish":"Sonuncu kim olmuş olabilir? / En son kim gelmiş acaba?","note":"'Wie mag ... zijn' = kim olabilir, spekülasyon içeren yapı. Belirsizlik ve tahmin birlikte. En son yapılan işleme gönderme yapılırken kullanılır.","etymology":"Belirsizlik ifadesi `mag` (olabilir) + `zijn` (olmak) — kesin olmayan bir tahmin.","uitleg":"Ik vraag me af wie er als laatste is geweest.","examples":[{"nl":"Wie mag de laatste geweest zijn die dit dossier heeft aangepast?","tr":"Bu dosyayı en son kim değiştirmiş olabilir?"},{"nl":"Wie mag de laatste geweest zijn om de cliënt te spreken?","tr":"Müşteriyle en son kim konuşmuş olabilir?"},{"nl":"Wie mag de laatste geweest zijn voor mij aan de beurt?","tr":"Benden önce sonuncu kim olmuş acaba?"}]},"after":{"dutch":"Wie was er als laatste?","turkish":"En son kim vardı?","note":"Ekipte kimin bir işi en son yaptığını sormak için “Wie heeft als laatste ...?” denebilir.","etymology":null,"uitleg":"Je vraagt wie het laatst aanwezig was.","examples":[{"nl":"Wie heeft als laatste iets aan het dossier toegevoegd?","tr":"Dosyaya en son kim bir şey ekledi?"},{"nl":"Wie heeft de cliënt het laatst gesproken?","tr":"Danışanla en son kim görüştü?"}]}},{"date":"15/07","head":"even piekeren","before":{"dutch":"even piekeren","turkish":"biraz düşünmek / kafa yormak / kaygılanmak","etymology":"`Piekeren` = tepe/uç anlamındaki `piek` kökünden — düşüncelerin \"sivri uçlarında\" dolaşmak.","note":"'Piekeren' = bir şey üzerinde sürekli düşünmek, kafayı takmak, kaygılanmak. 'Even' eklenince hafifler: biraz düşüneyim, bir dakika kafa yorayım. Hem olumlu (düşünme) hem endişe anlamında kullanılır.","uitleg":"Even goed nadenken over iets.","examples":[{"nl":"Laat me even piekeren over de beste aanpak.","tr":"En iyi yaklaşım üzerine biraz düşüneyim."},{"nl":"Hij zit de hele nacht te piekeren over zijn schulden.","tr":"Bütün gece borçları üzerine kafa yoruyor/kaygılanıyor."},{"nl":"Niet te veel piekeren — er is een oplossing.","tr":"Fazla kafa yorma — bir çözüm var."}]},"after":{"dutch":"piekeren","turkish":"kaygılanıp aynı şeyi tekrar tekrar düşünmek","etymology":null,"note":"Piekeren tekrarlayan ve kaygı veren düşünceleri anlatır. Bir yaklaşımı sakin biçimde değerlendirmek için nadenken kullanılır.","uitleg":"Steeds opnieuw aan iets denken waar je je zorgen over maakt.","examples":[{"nl":"Ik lig te piekeren over mijn schulden.","tr":"Yatakta borçlarımı düşünüp kaygılanıyorum."}]}},{"date":"27/07","head":"Nu zou ik zeggen...","before":{"examples":[{"nl":"Nu zou ik zeggen: dien het bezwaar zo snel mogelijk in.","tr":"Şimdi şunu söyleyebilirim: itirazı mümkün olan en kısa sürede sunun."},{"nl":"Nu zou ik zeggen dat u recht heeft op ondersteuning.","tr":"Benim görüşüm şu olurdu: desteğe hakkınız var."},{"nl":"Nu zou ik zeggen: wacht nog even af voordat u beslist.","tr":"Şu an şunu söyleyebilirim: karar vermeden önce biraz bekleyin."}]},"after":{"examples":[{"nl":"Nu zou ik zeggen: laten we in deze brief kijken welke termijn er staat.","tr":"Şu durumda önerim, mektupta hangi sürenin yazdığına birlikte bakmamız."},{"nl":"Nu zou ik zeggen dat u recht heeft op ondersteuning.","tr":"Benim görüşüm şu olurdu: desteğe hakkınız var."},{"nl":"Nu zou ik zeggen: wacht nog even af voordat u beslist.","tr":"Şu an şunu söyleyebilirim: karar vermeden önce biraz bekleyin."}]}},{"date":"STAJ","head":"Hij heeft een dikke bankrekening, dus hij heeft geen recht op toeslagen.","before":{"dutch":"Hij heeft een dikke bankrekening, dus hij heeft geen recht op toeslagen.","turkish":"Kabarık bir banka hesabı var, bu yüzden toeslag hakkı yok.","uitleg":"Zoveel geld hebben dat je geen recht meer hebt op overheidssteun.","etymology":"Yapı: `dikke bankrekening` (bkz. STAJ #69) + `geen recht op` (hakkı olmamak) örnek cümlesi.","note":"\"dikke bankrekening\" kelimesinin örnek cümlesinden eklendi.","examples":[{"nl":"Ondanks zijn dikke bankrekening vraagt hij toch toeslag aan.","tr":"Kabarık banka hesabına rağmen yine de toeslag başvurusu yapıyor."}]},"after":{"dutch":"Hij zegt zelf dat hij een dikke bankrekening heeft.","turkish":"Banka hesabında çok para olduğunu kendisi söylüyor.","uitleg":"De spreker haalt iemands eigen, informele woorden over geld aan.","etymology":null,"note":"Samimi dilde kullanılan mecazdır. Danışana mali durumunu sorarken tarafsız bir ifade kullan: “Welke inkomsten heeft u?”","examples":[{"nl":"Hoe zou u uw financiële situatie beschrijven?","tr":"Mali durumunuzu nasıl anlatırsınız?"}]}},{"date":"MOEST","head":"moest","before":{"examples":[{"nl":"Ik moest gisteren werken.","tr":"Dün çalışmam gerekiyordu."},{"nl":"Ze moest naar de dokter.","tr":"Doktora gitmesi gerekiyordu."},{"nl":"De cliënt moest binnen twee weken bezwaar maken.","tr":"Müvekkilin iki hafta içinde itiraz etmesi gerekiyordu."}]},"after":{"examples":[{"nl":"Ik moest gisteren werken.","tr":"Dün çalışmam gerekiyordu."},{"nl":"Ze moest naar de dokter.","tr":"Doktora gitmesi gerekiyordu."},{"nl":"Volgens deze brief moest de cliënt vóór de genoemde datum reageren.","tr":"Bu mektuba göre danışanın belirtilen tarihten önce yanıt vermesi gerekiyordu."}]}},{"date":"MOEST","head":"moest (beleefde vraag)","before":{"dutch":"moest (beleefde vraag)","turkish":"Ne alacaktınız? / Ne istemiştiniz?","note":"Winkel/balie context'inde beleefde vraag: gerçek bir zorunluluk değil, 'wat wilt u?' nun daha nazik/dolaylı bir versiyonu. Sanki müşterinin zaten bir isteği varmış gibi bir nezaket kalıbı.","etymology":"`Moest` burada gerçek zorunluluk değil, nazik soru kalıbı — bkz. #241.","uitleg":"Een beleefde manier om te vragen wat iemand wil, bijvoorbeeld in een winkel."},"after":{"dutch":"moest in een winkelvraag","turkish":"mağazada ne istendiğini sorarken kullanılan moest","note":"Mağazada duyabilirsin. Ses tonuna göre kısa veya sert gelebilir. Danışmada “Waarmee kan ik u helpen?” daha doğal bir açılıştır.","etymology":null,"uitleg":"In sommige winkelvragen verwijst moest naar wat de klant wilde bestellen."}},{"date":"STAJ","head":"Dit is een pro-forma melding, puur om de termijn te bewaken.","before":{"dutch":"Dit is een pro-forma melding, puur om de termijn te bewaken.","turkish":"Bu sadece süreyi korumak için yapılmış biçimsel bir bildirim.","uitleg":"Het is een melding voor de vorm: we doen het alleen om de termijn niet te missen."},"after":{"dutch":"Wat bedoelt de afzender hier met ‘pro forma’?","turkish":"Gönderen burada “pro forma” derken neyi kastediyor?","uitleg":"Je vraagt wat de term in deze specifieke brief betekent."}},{"date":"STAJ","head":"De pro-forma zitting is gepland voor volgende maand.","before":{"dutch":"De pro-forma zitting is gepland voor volgende maand.","turkish":"Biçimsel duruşma gelecek ay planlandı.","uitleg":"De korte rechtszitting waarin alleen de planning wordt besproken, is volgende maand."},"after":{"dutch":"Volgens de brief vindt de pro-formazitting volgende maand plaats.","turkish":"Mektuba göre davanın esasının ele alınmayacağı duruşma gelecek ay yapılacak.","uitleg":"De brief noemt de maand van de zitting. De zaak wordt dan nog niet inhoudelijk behandeld."}},{"date":"STAJ","head":"In dit kader heeft de cliënt recht op ondersteuning.","before":{"dutch":"In dit kader heeft de cliënt recht op ondersteuning.","turkish":"Bu çerçevede müşterinin desteğe hakkı bulunmaktadır.","uitleg":"Binnen deze regeling of situatie heeft de cliënt recht op hulp."},"after":{"dutch":"In dit kader wil de cliënt weten welke ondersteuning mogelijk is.","turkish":"Danışan bu bağlamda hangi desteğin mümkün olduğunu öğrenmek istiyor.","uitleg":"De cliënt vraagt welke hulp bij deze situatie past."}},{"date":"STAJ","head":"Hij heeft jaren WW opgebouwd en heeft nu recht op een uitkering.","before":{"dutch":"Hij heeft jaren WW opgebouwd en heeft nu recht op een uitkering.","turkish":"Yıllarca WW hakkı biriktirdi ve şimdi ödenek alma hakkı var.","uitleg":"Hij heeft lang gewerkt en daardoor nu recht op een WW-uitkering."},"after":{"dutch":"Hij wil weten welke WW-rechten hij tijdens zijn werk heeft opgebouwd.","turkish":"Çalıştığı süre içinde hangi işsizlik ödeneği haklarını biriktirdiğini öğrenmek istiyor.","uitleg":"Hij heeft een vraag over zijn arbeidsverleden en de WW."}},{"date":"08/07","head":"Wie mag de laatste geweest zijn om de cliënt te spreken?","before":{"dutch":"Wie mag de laatste geweest zijn om de cliënt te spreken?","turkish":"Müşteriyle en son kim konuşmuş olabilir?","uitleg":"Wie heeft als laatste met de cliënt gesproken?"},"after":{"dutch":"Wie heeft de cliënt het laatst gesproken?","turkish":"Danışanla en son kim görüştü?","uitleg":"Je vraagt een collega wie het meest recente gesprek met de cliënt heeft gevoerd."}},{"date":"27/07","head":"Nu zou ik zeggen: dien het bezwaar zo snel mogelijk in.","before":{"dutch":"Nu zou ik zeggen: dien het bezwaar zo snel mogelijk in.","turkish":"Şimdi şunu söyleyebilirim: itirazı mümkün olan en kısa sürede sunun.","uitleg":"Mijn advies is: stuur het bezwaar zo snel mogelijk in."},"after":{"dutch":"Nu zou ik zeggen: laten we in deze brief kijken welke termijn er staat.","turkish":"Şu durumda önerim, mektupta hangi sürenin yazdığına birlikte bakmamız.","uitleg":"Je stelt voor samen te kijken welke termijn de brief noemt."}},{"date":"15/07","head":"Laat me even piekeren over de beste aanpak.","before":{"dutch":"Laat me even piekeren over de beste aanpak.","turkish":"En iyi yaklaşım üzerine biraz düşüneyim.","uitleg":"Geef me even tijd om na te denken over de beste manier.","note":"\"even piekeren\" kelimesinin örnek cümlesinden eklendi."},"after":{"dutch":"Laat me even nadenken over de beste aanpak.","turkish":"En uygun yaklaşımı biraz düşüneyim.","uitleg":"Je vraagt even tijd om een aanpak te bedenken.","note":"Bir çözüm düşünmek için nadenken kullanılır. Piekeren kaygıyla aynı şeyi tekrar tekrar düşünmektir."}},{"date":"15/07","head":"Niet te veel piekeren — er is een oplossing.","before":{"dutch":"Niet te veel piekeren — er is een oplossing.","turkish":"Fazla kafa yorma — bir çözüm var.","uitleg":"Maak je niet te veel zorgen; er is een oplossing."},"after":{"dutch":"Ik lig te piekeren over mijn schulden.","turkish":"Yatakta borçlarımı düşünüp kaygılanıyorum.","uitleg":"De spreker vertelt dat de zorgen over geld blijven terugkomen."}},{"date":"02/09","head":"toeslagenaffaire","before":{"legal":"Wet hersteloperatie toeslagen (2023) ile düzenlenmiş bir telafi rejimi. Belastingdienst/Toeslagen etnik profilleme ve orantısız fraude tespiti yaptı; binlerce aile haksız yere borçlandırıldı. Mağdurların 30.000 euro forfaitair tazminat + ek zarar + borç silme hakkı var. Türk hukukunda karşılaştırılabilir tek bir örnek yok; idarenin ağır hizmet kusuru sayılabilir.","note":"Hollanda'nın en büyük idari skandallarından. 2019-2021 arası ortaya çıktı, hükümetin istifasına yol açtı. Sociaal raadsman olarak mağdurlarla karşılaşman çok olası.","examples":[{"nl":"De toeslagenaffaire heeft duizenden gezinnen geraakt.","tr":"Toeslag skandalı binlerce aileyi etkiledi."},{"nl":"Gedupeerden van de toeslagenaffaire krijgen herstel.","tr":"Toeslag skandalı mağdurları telafi alıyor."},{"nl":"De toeslagenaffaire leidde tot het aftreden van het kabinet.","tr":"Toeslag skandalı kabinenin istifasına yol açtı."}]},"after":{"legal":null,"note":"Çocuk bakım yardımıyla ilgili skandalı anlatan terim. Bir danışanın kişisel sürecini konuşurken aldığı yazıdan hareket et.","examples":[{"nl":"De toeslagenaffaire heeft duizenden gezinnen geraakt.","tr":"Çocuk bakım yardımı skandalı binlerce aileyi etkiledi."},{"nl":"Een gedupeerde van de toeslagenaffaire heeft een vraag over haar hersteltraject.","tr":"Çocuk bakım yardımı skandalından zarar gören bir kadın telafi süreciyle ilgili bir soru soruyor."},{"nl":"De toeslagenaffaire leidde tot het aftreden van het kabinet.","tr":"Çocuk bakım yardımı skandalı kabinenin istifasına yol açtı."}]}},{"date":"STAJ","head":"U dient woonachtig te zijn in Nederland om in aanmerking te komen.","before":{"dutch":"U dient woonachtig te zijn in Nederland om in aanmerking te komen.","turkish":"Hak kazanabilmek için Hollanda'da ikamet etmeniz gerekmektedir.","uitleg":"U moet in Nederland wonen om hier recht op te hebben."},"after":{"dutch":"Op het formulier wordt gevraagd of u in Nederland woonachtig bent.","turkish":"Formda Hollanda’da ikamet edip etmediğiniz soruluyor.","uitleg":"Het formulier vraagt naar het land waar u woont."}},{"date":"STAJ","head":"U hoeft niet aanwezig te zijn bij de pro-forma zitting.","before":{"dutch":"U hoeft niet aanwezig te zijn bij de pro-forma zitting.","turkish":"Biçimsel duruşmada bulunmanız gerekmez.","uitleg":"U hoeft niet naar de korte planningszitting te komen."},"after":{"dutch":"Staat er in de oproep of u bij de pro-formazitting aanwezig moet zijn?","turkish":"Çağrı yazısında bu duruşmaya katılmanız gerekip gerekmediği yazıyor mu?","uitleg":"Je vraagt wat de oproep zegt over aanwezigheid bij deze zitting."}},{"date":"STAJ","head":"Degene die de aanvraag heeft ingediend, moet aanwezig zijn.","before":{"dutch":"Degene die de aanvraag heeft ingediend, moet aanwezig zijn.","turkish":"Başvuruyu yapan kişinin hazır bulunması gerekir.","uitleg":"De persoon die de aanvraag heeft gedaan, moet erbij zijn."},"after":{"dutch":"Staat in de uitnodiging dat degene die de aanvraag heeft ingediend, erbij moet zijn?","turkish":"Davette başvuruyu yapan kişinin katılması gerektiği yazıyor mu?","uitleg":"Je kijkt wie volgens deze uitnodiging aanwezig moet zijn."}},{"date":"STAJ","head":"De gemeente beoordeelt de aanvraag binnen acht weken.","before":{"dutch":"De gemeente beoordeelt de aanvraag binnen acht weken.","turkish":"Belediye başvuruyu sekiz hafta içinde değerlendirir.","uitleg":"De gemeente bekijkt de aanvraag en beslist binnen acht weken."},"after":{"dutch":"Staat in de brief wanneer de gemeente uw aanvraag beoordeelt?","turkish":"Mektupta belediyenin başvurunuzu ne zaman değerlendireceği yazıyor mu?","uitleg":"Je zoekt in de brief naar informatie over de beoordeling."}},{"date":"STAJ","head":"Er is een acceptgiro meegestuurd met de huurrekening.","before":{"dutch":"Er is een acceptgiro meegestuurd met de huurrekening.","turkish":"Kira faturasıyla birlikte bir ödeme formu gönderilmiş.","uitleg":"Bij de rekening voor de huur zit een formulier om te betalen."},"after":{"dutch":"Bij een oude huurrekening vond ik een acceptgiro.","turkish":"Eski bir kira faturasıyla birlikte bir ödeme formu buldum.","uitleg":"De spreker vond een vroeger gebruikt betaalformulier bij een oude rekening."}},{"date":"STAJ","head":"U denkt dat hij recht heeft, maar dat is niet het geval.","before":{"dutch":"U denkt dat hij recht heeft, maar dat is niet het geval.","turkish":"Hakkı olduğunu düşünüyorsunuz, ama durum böyle değil.","uitleg":"U denkt dat hij er recht op heeft, maar dat klopt niet."},"after":{"dutch":"U dacht dat de brief al verstuurd was, maar dat is niet het geval.","turkish":"Mektubun gönderildiğini düşünüyordunuz ama henüz gönderilmedi.","uitleg":"Je verduidelijkt dat de brief nog niet is verstuurd."}},{"date":"STAJ","head":"De termijn loopt binnenkort af, actie is vereist.","before":{"dutch":"De termijn loopt binnenkort af, actie is vereist.","turkish":"Süre yakında dolacak, eylem gerekiyor.","uitleg":"De tijd is bijna om; u moet nu iets doen."},"after":{"dutch":"Volgens de brief loopt de termijn binnenkort af. Welke datum staat er precies?","turkish":"Mektuba göre süre yakında doluyor. Tam olarak hangi tarih yazıyor?","uitleg":"Je controleert de datum in deze brief."}},{"date":"17/06","head":"Het is belangrijk om alle inkomsten te vermelden.","before":{"dutch":"Het is belangrijk om alle inkomsten te vermelden.","turkish":"Tüm gelirleri belirtmek önemlidir.","uitleg":"Het is belangrijk dat u al uw inkomsten opschrijft of noemt."},"after":{"dutch":"Welke inkomsten moet u op dit formulier vermelden?","turkish":"Bu formda hangi gelirleri belirtmeniz gerekiyor?","uitleg":"Je vraagt naar de inkomsten die dit formulier noemt."}},{"date":"MOEST","head":"De cliënt moest binnen twee weken bezwaar maken.","before":{"dutch":"De cliënt moest binnen twee weken bezwaar maken.","turkish":"Müvekkilin iki hafta içinde itiraz etmesi gerekiyordu.","uitleg":"De cliënt had maar twee weken om bezwaar te maken."},"after":{"dutch":"Volgens deze brief moest de cliënt vóór de genoemde datum reageren.","turkish":"Bu mektuba göre danışanın belirtilen tarihten önce yanıt vermesi gerekiyordu.","uitleg":"Moest verwijst naar wat er in deze brief van de cliënt werd gevraagd."}},{"date":"MOEST","head":"Wat moest het zijn?","before":{"uitleg":"Een beleefde vraag in de winkel: wat wilt u kopen?","note":"\"moest\" kelimesinin örnek cümlesinden eklendi."},"after":{"uitleg":"Een vraag die je in een winkel kunt horen bij het opnemen van een bestelling.","note":"Mağazada duyabileceğin bir kalıp. Danışanla ilk görüşmede “Waarmee kan ik u helpen?” diyebilirsin."}},{"date":"MOEST","head":"Wat moest u hebben?","before":{"turkish":"Neyi istemiştiniz?","uitleg":"Een beleefde vraag aan de balie of in de winkel: wat wilt u?","note":"\"moest\" kelimesinin örnek cümlesinden eklendi."},"after":{"turkish":"Ne istemiştiniz?","uitleg":"Een korte vraag die je in een winkel kunt horen. Afhankelijk van de toon kan die bot klinken.","note":"Mağazada duyabileceğin bir kalıp. Danışanla ilk görüşmede “Waarmee kan ik u helpen?” diyebilirsin."}},{"date":"MOEST","head":"Moest er nog iets bij?","before":{"turkish":"Başka bir şey ister miydiniz?","uitleg":"Een beleefde vraag: wilt u nog iets anders erbij?","note":"\"moest\" kelimesinin örnek cümlesinden eklendi."},"after":{"turkish":"Başka bir şey de istemiş miydiniz?","uitleg":"In een winkel vraagt iemand of je nog iets bij je bestelling wilde hebben.","note":"Mağazada duyabileceğin bir kalıp. Danışanla ilk görüşmede “Waarmee kan ik u helpen?” diyebilirsin."}},{"date":"STAJ","head":"De verzorgende ouder ontvangt de kinderbijslag.","before":{"dutch":"De verzorgende ouder ontvangt de kinderbijslag.","turkish":"Bakım veren ebeveyn çocuk yardımını alır.","uitleg":"De ouder bij wie de kinderen wonen, krijgt de kinderbijslag."},"after":{"dutch":"De verzorgende ouder heeft een vraag over de kinderbijslag.","turkish":"Çocuğun günlük bakımını üstlenen ebeveynin çocuk parasıyla ilgili bir sorusu var.","uitleg":"Een ouder wil iets weten over de kinderbijslag."}},{"date":"02/09","head":"Gedupeerden van de toeslagenaffaire krijgen herstel.","before":{"dutch":"Gedupeerden van de toeslagenaffaire krijgen herstel.","turkish":"Toeslag skandalı mağdurları telafi alıyor.","uitleg":"Mensen die door de toeslagenaffaire benadeeld zijn, krijgen hulp en geld terug."},"after":{"dutch":"Een gedupeerde van de toeslagenaffaire heeft een vraag over haar hersteltraject.","turkish":"Çocuk bakım yardımı skandalından zarar gören bir kadın, telafi süreci hakkında bir soru soruyor.","uitleg":"De vrouw vraagt naar het verloop van haar eigen hersteltraject."}},{"date":"10/11","head":"Helaas heeft ze spoedcriteria.","before":{"dutch":"Helaas heeft ze spoedcriteria.","turkish":"Ne yazık ki acil durum kriterlerini karşılıyor.","uitleg":"Haar situatie is zo ernstig dat ze voor spoed in aanmerking komt.","note":"Bu cümledeki 'spoedcriteria hebben' doğal bir Hollandaca kullanımı değildir. 'Ze voldoet aan de spoedcriteria' (kriterleri karşılıyor) veya 'Ze voldoet niet aan de spoedcriteria' (karşılamıyor) seçenekleri vardır. Hangisinin kastedildiği orijinal bağlamdan doğrulanmalı.","examples":[{"nl":"Helaas voldoet hij aan de spoedcriteria.","tr":"Ne yazık ki acil kriterlerini karşılıyor."},{"nl":"Zij komt in aanmerking voor spoed.","tr":"Acil için uygun görülüyor."},{"nl":"De spoedcriteria zijn nog niet bepaald.","tr":"Acil kriterleri henüz belirlenmedi."}]},"after":{"dutch":"Voldoet zij aan de spoedcriteria?","turkish":"Durumu, acil değerlendirme ölçütlerini karşılıyor mu?","uitleg":"Je vraagt of deze situatie aan de criteria voor spoed voldoet. Het antwoord staat nog open.","note":"Kaynak notunda ölçütlerin karşılanıp karşılanmadığı belirsiz. Ekipte bunu açıklığa kavuşturmak için soru sorabilirsin.","examples":[{"nl":"Welke spoedcriteria bedoel je?","tr":"Hangi acil değerlendirme ölçütlerini kastediyorsun?"}]}},{"date":"27/05","head":"een regeling treffen","before":{"examples":[{"nl":"We moeten een regeling treffen voor de huurachterstand.","tr":"Kira borcunun gecikmesi için bir düzenleme yapmalıyız."},{"nl":"Ik heb een betalingsregeling getroffen met de schuldeiser.","tr":"Alacaklıyla bir ödeme planı yaptım."},{"nl":"Kunnen we een regeling treffen zodat hij zijn rekeningen kan betalen?","tr":"Faturalarını ödeyebilmesi için bir düzenleme yapabilir miyiz?"}]},"after":{"examples":[{"nl":"We moeten een regeling treffen voor de huurachterstand.","tr":"Biriken kira borcu için bir anlaşma yapmamız gerekiyor."},{"nl":"Ik heb een betalingsregeling getroffen met de schuldeiser.","tr":"Alacaklıyla bir ödeme planı yaptım."},{"nl":"Kunnen we een regeling treffen zodat hij zijn rekeningen kan betalen?","tr":"Faturalarını ödeyebilmesi için bir düzenleme yapabilir miyiz?"}]}},{"date":"27/05","head":"Daarvoor moeten we SHV vragen.","before":{"dutch":"Daarvoor moeten we SHV vragen.","turkish":"Bunun için SHV'ye sormamız / başvurmamız gerekiyor.","note":"'Daarvoor' = bunun için. SHV = Stichting Hulp Verlening veya bağlama göre başka kuruluş kısaltması. Yönlendirme cümlesi.","examples":[{"nl":"De cliënt heeft extra ondersteuning nodig. Daarvoor moeten we SHV vragen.","tr":"Müşterinin ekstra desteğe ihtiyacı var. Bunun için SHV'ye başvurmamız gerekiyor."},{"nl":"Daarvoor moeten we SHV vragen, dat valt buiten ons takenpakket.","tr":"Bu bizim görev alanımızın dışında, bunun için SHV'ye sormamız gerek."},{"nl":"Ik denk dat we daarvoor SHV moeten inschakelen.","tr":"Bunun için SHV'yi devreye almamız gerektiğini düşünüyorum."}],"uitleg":"Voor deze vraag hebben we informatie of hulp van schuldhulpverlening nodig."},"after":{"dutch":"Dat kunnen we aan de schuldhulpverlening vragen.","turkish":"Bunu borç danışma birimine sorabiliriz.","note":"Bu örnekte SHV, schuldhulpverlening (borç danışmanlığı) için kullanılıyor. Görüşmede tam adını söyleyebilirsin.","examples":[{"nl":"Zullen we samen de schuldhulpverlening bellen?","tr":"Borç danışma birimini birlikte arayalım mı?"},{"nl":"Mag ik uw vraag aan de schuldhulpverlening voorleggen?","tr":"Sorunuzu borç danışma birimine iletebilir miyim?"}],"uitleg":"Je stelt voor om advies te vragen over schulden."}},{"date":"27/05","head":"Ik kan je aanmelden.","before":{"type":"woord","turkish":"Seni kaydedebilirim / başvurunuzu yapabilirim.","note":"'Aanmelden' = kayıt yaptırmak, başvuru yapmak. Sosyal hizmetlerde bir programa veya kuruma kayıt için çok kullanılır.","legal":"Türk hukukunda 'başvuru yapmak' veya 'müracaat'. İdari hukuk bağlamında önemli adım — aanmelding olmadan hizmet akışı başlamaz.","is_legal":true,"examples":[{"nl":"Ik kan je aanmelden voor de schuldhulpverlening.","tr":"Seni borç yardım hizmetine kaydedebilirim."},{"nl":"Wil je dat ik je aanmeld bij de voedselbank?","tr":"Seni gıda bankasına kaydettirmemi ister misin?"},{"nl":"Ik kan je aanmelden, maar je hebt wel een DigiD nodig.","tr":"Seni kayıt edebilirim ama DigiD'e ihtiyacın var."}]},"after":{"type":"zin","turkish":"İstersen senin adına başvuru yapabilirim.","note":"Je ve jou samimi hitap biçimleridir. Resmî hitapta “Ik kan u aanmelden” denir.","legal":null,"is_legal":false,"examples":[{"nl":"Wil je dat ik je aanmeld?","tr":"Senin adına başvuru yapmamı ister misin?"},{"nl":"Zullen we samen kijken wat je nodig hebt voor de aanmelding?","tr":"Başvuru için neye ihtiyacın olduğuna birlikte bakalım mı?"}]}},{"date":"27/05","head":"Er is geen ruimte om nieuw toe te voegen.","before":{"dutch":"Er is geen ruimte om nieuw toe te voegen.","turkish":"Yeni ekleme yapmak için alan / kapasite yok.","examples":[{"nl":"Het systeem is vol. Er is geen ruimte om nieuw toe te voegen.","tr":"Sistem dolu. Yeni ekleme yapmak için alan yok."},{"nl":"Er is op dit moment geen ruimte om nieuwe cliënten toe te voegen.","tr":"Şu an yeni müşteri eklemek için kapasite yok."},{"nl":"Er is geen budgetruimte om dit toe te voegen aan het pakket.","tr":"Bu pakete ekleme yapmak için bütçe alanı yok."}]},"after":{"dutch":"Er is geen ruimte om iets nieuws toe te voegen.","turkish":"Yeni bir şey eklemek için yer yok.","examples":[{"nl":"De agenda is vol. Er is geen ruimte om iets nieuws toe te voegen.","tr":"Gündem dolu. Yeni bir şey eklemeye yer yok."}]}},{"date":"20/05","head":"OVH (beschermd)","before":{"turkish":"Korunan statü / Koruma altında","note":"OVH = 'Onder Voorbehoud van Hypotheek' veya bağlama göre 'Onder Voogdij Hulpverlening'. 'Beschermd' = korunmuş. Dossier veya systeem kaydında görülür.","examples":[{"nl":"Dit dossier is OVH beschermd, je hebt speciale toegang nodig.","tr":"Bu dosya OVH korumalı, özel erişim yetkisi gerekiyor."},{"nl":"De cliënt staat OVH geregistreerd in het systeem.","tr":"Müşteri sistemde OVH olarak kayıtlı."},{"nl":"Je kunt dit niet zomaar wijzigen, het is beschermd.","tr":"Bunu öylece değiştiremezsin, korumalı statüde."}],"legal":"Hukuki bağlamda 'beschermd' = koruma altında. Voogdij = velayet/vesayet. Türk hukukunda 'vesayet altına alınmış kişi' karşılığı.","is_legal":true},"after":{"turkish":"beschermd = korumalı. OVH kısaltmasının buradaki anlamı belirsiz.","note":"Kaynak notunda kısaltmanın açılımı yok. Ekipten bağlamını sor.","examples":[{"nl":"Waar staat OVH hier voor?","tr":"Burada OVH neyin kısaltması?"}],"legal":null,"is_legal":false},"review":true},{"date":"20/05","head":"Ben ik je gelegen?","before":{"dutch":"Ben ik je gelegen?","turkish":"Seni rahatsız ediyor muyum? / Uygun bir zamanda mı arıyorum?","note":"Çok kibar ve düşünceli bir soru. 'Gelegen' = uygun, müsait. 'Kom ik gelegen?' de aynı anlamda kullanılır.","examples":[{"nl":"Hoi, ben ik je gelegen? Ik had een korte vraag.","tr":"Merhaba, seni rahatsız ediyor muyum? Kısa bir sorum vardı."},{"nl":"Ben ik je gelegen of bel ik op een slecht moment?","tr":"Uygun bir zamanda mı arıyorum, yoksa kötü bir anda mı?"},{"nl":"Sorry, ben ik je gelegen? Ik kan ook later terugkomen.","tr":"Özür dilerim, rahatsız ettim mi? Daha sonra da gelebilirim."}]},"after":{"dutch":"Bel ik je gelegen?","turkish":"Uygun bir zamanda mı arıyorum?","note":"Telefon görüşmesinin başında kullanılır. Yüz yüze “Kom ik gelegen?” diyebilirsin.","examples":[{"nl":"Goedemorgen, bel ik gelegen?","tr":"Günaydın, uygun bir zamanda mı arıyorum?"},{"nl":"Kom ik gelegen of zal ik later terugkomen?","tr":"Şimdi uygun mu, yoksa daha sonra mı geleyim?"}]}},{"date":"13/05","head":"zienswijze","before":{"turkish":"görüş / bakış açısı / resmi itiraz görüşü","note":"Hem günlük dilde 'bakış açısı' hem de idare hukukunda resmi bir terim: bir plan veya besluit hakkında yazılı görüş bildirme. Bezwaar'dan önce gelen daha erken bir katılım biçimi.","legal":"Türk idare hukukunda 'görüş bildirme' veya 'itiraz'. Hollanda'da Wet ruimtelijke ordening ve Awb çerçevesinde zienswijze, een besluit kesinleşmeden önce sunulan resmi görüştür. Bezwaar'dan farklıdır: zienswijze een ontwerp-besluit'e karşı sunulur.","examples":[{"nl":"U kunt een zienswijze indienen tegen het bestemmingsplan.","tr":"İmar planına karşı resmi görüş bildirebilirsiniz."},{"nl":"Wat is uw zienswijze op dit voorstel?","tr":"Bu teklife ilişkin görüşünüz nedir?"},{"nl":"De gemeente heeft alle zienswijzen bekeken voor het definitieve besluit.","tr":"Belediye, kesin karardan önce tüm görüşleri inceledi."}]},"after":{"turkish":"görüş / bir plan veya öneri hakkında bildirilen görüş","note":"Bir yazıda zienswijze sözcüğünü gördüğünde hangi plan veya önerinin kastedildiğine bak.","legal":null,"examples":[{"nl":"In de brief staat het woord ‘zienswijze’. Wat betekent dat?","tr":"Mektupta “zienswijze” sözcüğü geçiyor. Bu ne demek?"},{"nl":"Wat is uw zienswijze op dit voorstel?","tr":"Bu öneri hakkındaki görüşünüz nedir?"}]}},{"date":"21/05","head":"warme overdracht","before":{"turkish":"sıcak devir / kişisel geçiş desteği","note":"Sosyal hizmetlerde çok önemli bir kavram. Bir müşteriyi sadece dosya devretmek değil, yeni yardımcıya bizzat tanıtmak / köprü kurmak. 'Warm' = kişisel, bağlantılı; karşıtı 'koude overdracht' = sadece belge devri.","legal":"Türk sosyal hizmet terminolojisinde 'vaka transferi' veya 'kişisel yönlendirme'. Wmo ve Jeugdwet'te continuïteit van zorg ilkesiyle ilişkilidir.","is_legal":true,"examples":[{"nl":"We doen een warme overdracht zodat de cliënt niet opnieuw alles hoeft te vertellen.","tr":"Müşterinin her şeyi yeniden anlatmak zorunda kalmaması için sıcak devir yapıyoruz."},{"nl":"Ik stel je voor aan mijn collega, dit is een warme overdracht.","tr":"Seni meslektaşıma tanıştırıyorum — bu bir sıcak devirdir."},{"nl":"Een warme overdracht verhoogt de kans dat de cliënt de hulp ook echt oppakt.","tr":"Sıcak devir, müşterinin yardımı gerçekten devam ettirme ihtimalini artırır."}]},"after":{"turkish":"danışanı yeni uzmana bizzat tanıştırarak yönlendirme","note":"Ekip içinde “warme overdracht” denebilir. Danışana ne yapmayı önerdiğini somut bir cümleyle anlat.","legal":null,"is_legal":false,"examples":[{"nl":"Wilt u dat ik u aan mijn collega voorstel?","tr":"Sizi meslektaşımla tanıştırmamı ister misiniz?"},{"nl":"We hebben met haar besproken wat ze bij de warme overdracht wil vertellen.","tr":"Yeni uzmanla tanışırken neleri anlatmak istediğini kendisiyle konuştuk."}]}},{"date":"08/06","head":"Ben je geopereerd aan je maag?","before":{"turkish":"Midenizden ameliyat oldunuz mu?","note":"Intake veya gezondheidsanamnese sırasında sorulan bir soru. Sosyal raadsman olarak sağlık durumunu anlamak, doğru yardım veya uitkering hakkı için gerekli olabilir.","examples":[{"nl":"Ben je geopereerd aan je maag? Dat kan invloed hebben op je uitkering.","tr":"Midenizden ameliyat oldunuz mu? Bu yardım ödemelerinizi etkileyebilir."},{"nl":"Is er ooit een operatie geweest aan je maag of darmen?","tr":"Mide veya bağırsaklarınızda daha önce bir ameliyat oldu mu?"},{"nl":"Voor de WIA-aanvraag is het belangrijk om medische ingrepen te vermelden.","tr":"WIA başvurusu için tıbbi müdahaleleri belirtmek önemli."}]},"after":{"turkish":"Midenden ameliyat oldun mu?","note":"Je samimi hitaptır. Sağlıkla ilgili bir konuşmada duyulabilecek bir sorudur.","examples":[{"nl":"Ik ben aan mijn maag geopereerd.","tr":"Midemden ameliyat oldum."},{"nl":"U vertelde dat u geopereerd bent. Waarmee kan ik u vandaag helpen?","tr":"Ameliyat olduğunuzu söylediniz. Bugün size hangi konuda yardımcı olabilirim?"}]}},{"date":"STAJ","head":"reïntegreren","before":{"dutch":"reïntegreren","turkish":"yeniden entegre olmak / işe dönüş sürecine girmek","note":"Sosyal hizmetlerde çok kullanılır. Özellikle WIA/WW kapsamında işten uzak kalan kişinin iş hayatına geri dönüş sürecini ifade eder. 'Reïntegratietraject' = bu sürecin planı.","legal":"Türk hukukunda 'mesleki rehabilitasyon' veya 'işe yeniden uyum'. Hollanda'da Wet WIA md. 25 kapsamında werkgever reïntegratieplicht (işveren yükümlülüğü) taşır. Spoor 1 (kendi işverene dönüş) ve Spoor 2 (başka işverene geçiş) ayrımı önemlidir.","is_legal":true,"examples":[{"nl":"De cliënt is bezig te reïntegreren na een lange ziekteperiode.","tr":"Müşteri uzun bir hastalık döneminin ardından işe dönüş sürecinde."},{"nl":"UWV begeleidt hem bij het reïntegreren.","tr":"UWV onu işe yeniden entegre olma sürecinde destekliyor."},{"nl":"Het reïntegreren gaat langzaam maar gestaag.","tr":"Yeniden entegrasyon yavaş ama istikrarlı ilerliyor."}]},"after":{"dutch":"re-integreren","turkish":"işe yeniden uyum sağlamak / işe dönüş sürecinde olmak","note":"İsim biçimi “re-integratie”, fiil biçimi “re-integreren”.","legal":null,"is_legal":false,"examples":[{"nl":"Ik ben na mijn ziekte aan het re-integreren.","tr":"Hastalığımdan sonra işe dönüş sürecindeyim."},{"nl":"Hoe gaat het met uw re-integratie?","tr":"İşe dönüş süreciniz nasıl gidiyor?"}]}},{"date":"STAJ","head":"in aanmerking (komen)","before":{"dutch":"in aanmerking (komen)","turkish":"hak kazanmak / dikkate alınmak / uygun olmak","note":"'In aanmerking komen voor iets' = bir şeye hak kazanmak, uygun olmak. Sosyal hizmetlerde en çok kullanılan ifadelerden biri. 'In aanmerking nemen' = dikkate almak.","legal":"Türk hukukunda 'hak kazanmak' veya 'yararlanmak'. Bestuursrechtelijk: 'recht hebben op' ile eş anlamlı kullanılır ama 'in aanmerking komen' daha geniş — hem hak hem uygunluk kriterini kapsar.","examples":[{"nl":"Komt hij in aanmerking voor huurtoeslag?","tr":"Kira yardımı almaya hak kazanıyor mu?"},{"nl":"U komt niet in aanmerking voor deze regeling vanwege uw inkomen.","tr":"Geliriniz nedeniyle bu düzenlemeye uygun değilsiniz."},{"nl":"We nemen alle omstandigheden in aanmerking bij de beoordeling.","tr":"Değerlendirmede tüm koşulları dikkate alıyoruz."}]},"after":{"dutch":"in aanmerking komen voor","turkish":"bir şey için uygun olmak / koşulları karşılamak","note":"Ardından “voor” ve başvurulan yardım ya da hizmet gelir.","legal":null,"examples":[{"nl":"Ik wil weten of ik voor deze regeling in aanmerking kom.","tr":"Bu düzenlemeden yararlanma koşullarını karşılayıp karşılamadığımı öğrenmek istiyorum."}]}},{"date":"STAJ","head":"acceptgiro","before":{"turkish":"ödeme fişi / ödeme formu / giro makbuzu","note":"Eski usul kâğıt ödeme formu. Artık dijital ortamda da 'acceptgiro' denilir. Fatura veya borç bildirimiyle birlikte gelen, bankaya götürülerek ödeme yapılabilen belge. Dijital bankacılığa geçmeyen yaşlı müşterilerde sık karşılaşılır.","examples":[{"nl":"Er is een acceptgiro meegestuurd met de huurrekening.","tr":"Kira faturasıyla birlikte bir ödeme formu gönderilmiş."},{"nl":"Hij weet niet hoe hij de acceptgiro moet betalen.","tr":"Ödeme formunu nasıl ödeyeceğini bilmiyor."},{"nl":"Je kunt de acceptgiro inleveren bij de bank of online betalen.","tr":"Ödeme formunu bankaya teslim edebilir ya da online ödeyebilirsin."}]},"after":{"turkish":"eskiden kullanılan basılı ödeme formu","note":"Eski evraklarda ve geçmişte yapılan ödemeler anlatılırken karşılaşabileceğin bir sözcük.","examples":[{"nl":"Bij mijn oude papieren lag nog een acceptgiro.","tr":"Eski evraklarımın arasında bir ödeme formu vardı."}]}},{"date":"STAJ","head":"bekeuring","before":{"note":"Polis tarafından verilen ceza belgesi. Mulderboete'den fark: bekeuring daha geniş kapsamlı, Mulderboete ise idari sistem kapsamındaki trafik ihlallerine özel.","legal":"Türk hukukunda 'trafik cezası' veya 'idari para cezası'. CJIB bağlamında sociaal raadsman için önemli — ödenmezse verhoogd wordt en invordering volgt.","examples":[{"nl":"Hij heeft een bekeuring gekregen wegens te hard rijden.","tr":"Hız ihlali nedeniyle trafik cezası aldı."},{"nl":"De bekeuring moet binnen zes weken betaald worden.","tr":"Trafik cezası altı hafta içinde ödenmelidir."},{"nl":"Je kunt bezwaar maken tegen een bekeuring.","tr":"Bir trafik cezasına itiraz edebilirsin."}]},"after":{"note":"Özellikle trafik bağlamında duyabileceğin “para cezası” sözcüğü.","legal":null,"examples":[{"nl":"Ik heb een bekeuring gekregen.","tr":"Para cezası aldım."},{"nl":"Welke betaaldatum staat er in de brief over de bekeuring?","tr":"Cezayla ilgili mektupta hangi ödeme tarihi yazıyor?"}]}},{"date":"STAJ","head":"Wat staat daar in?","before":{"dutch":"Wat staat daar in?","turkish":"Orada ne yazıyor? / İçinde ne var?","examples":[{"nl":"Wat staat daar in? Ik begrijp de brief niet.","tr":"Orada ne yazıyor? Mektubu anlamıyorum."},{"nl":"Wat staat er precies in dat besluit?","tr":"O kararda tam olarak ne yazıyor?"},{"nl":"Kunt u mij uitleggen wat er in dit formulier staat?","tr":"Bu formda ne yazdığını açıklar mısınız?"}]},"after":{"dutch":"Wat staat daarin?","turkish":"İçinde ne yazıyor?","examples":[{"nl":"Wat staat daarin? Ik begrijp de brief niet.","tr":"İçinde ne yazıyor? Mektubu anlamıyorum."},{"nl":"Zullen we samen kijken wat erin staat?","tr":"İçinde ne yazdığına birlikte bakalım mı?"}]}},{"date":"STAJ","head":"Wat dan de juiste route is?","before":{"dutch":"Wat dan de juiste route is?","turkish":"Hangi yolun doğru olduğu? / Doğru yöntem nedir?","note":"Çoğunlukla dolaylı soru olarak kullanılır: 'Ik vraag me af wat dan de juiste route is.' = Doğru yolun ne olduğunu merak ediyorum. Başvuru veya beroep süreçlerinde sıkça sorulan soru."},"after":{"dutch":"Wat is dan de juiste route?","turkish":"Peki, hangi yolu izlemek uygun olur?","note":"Doğrudan soruda “Wat is dan de juiste route?” denir. Dolaylı soruda fiil sona gelir: “Ik vraag me af wat dan de juiste route is.”"}},{"date":"STAJ","head":"urgentieverklaring","before":{"turkish":"acil konut ihtiyacı belgesi / öncelikli konut başvurusu","note":"Normale konut sırası beklemek yerine öncelikli olarak konut tahsisi için verilen resmi belge. Belediye veya woningcorporatie tarafından verilir. Çok ciddi durumlar için (dakloosheid, vlucht uit onveilige situatie).","legal":"Türk hukukunda doğrudan karşılığı yok; 'öncelikli konut tahsisi'. Hollanda'da Huisvestingswet 2014 kapsamında. Urgentiecriteria: medische, sociale, of veiligheidssituatie. Woningcorporatie kendi urgentiebeleid'ini uygular.","examples":[{"nl":"Ze heeft een urgentieverklaring aangevraagd omdat ze dakloos is.","tr":"Evsiz olduğu için acil konut ihtiyacı belgesi başvurdu."},{"nl":"Met een urgentieverklaring kom je sneller in aanmerking voor een woning.","tr":"Acil konut belgesiyle konuta daha hızlı hak kazanırsın."},{"nl":"De gemeente beoordeelt de urgentieverklaring binnen vier weken.","tr":"Belediye acil konut belgesini dört hafta içinde değerlendirir."}]},"after":{"turkish":"konut ararken öncelik sağlayabilen belge","note":"Verklaring burada belgenin adıdır. “Een urgentieverklaring aanvragen” bu belge için başvurmak demektir.","legal":null,"examples":[{"nl":"Ik heb een brief over mijn urgentieverklaring gekregen.","tr":"Konut öncelik belgemle ilgili bir mektup aldım."},{"nl":"Heeft u de brief over uw aanvraag bij u?","tr":"Başvurunuzla ilgili mektup yanınızda mı?"}]}},{"date":"STAJ","head":"seksueel misbruik","before":{"turkish":"cinsel istismar / cinsel taciz","note":"'Misbruik' = kötüye kullanma, istismar. 'Seksueel misbruik' = cinsel istismar, özellikle güç ilişkisi bağlamında (çocuklar, bağımlı bireyler). Sosyal hizmetlerde bildirme yükümlülüğü doğurabilir.","legal":"Türk Ceza Kanunu md. 102-105 cinsel suçlar. Hollanda WvSr md. 242-249 verkrachting en ontucht. Meldcode Huiselijk Geweld en Kindermishandeling kapsamında sociaal werkers meldplicht taşır.","examples":[{"nl":"Er zijn vermoedens van seksueel misbruik, we melden dit bij Veilig Thuis.","tr":"Cinsel istismar şüphesi var, bunu Veilig Thuis'a bildiriyoruz."},{"nl":"Slachtoffers van seksueel misbruik hebben recht op professionele hulp.","tr":"Cinsel istismar mağdurlarının profesyonel yardıma hakkı var."},{"nl":"Seksueel misbruik is strafbaar en dient gemeld te worden.","tr":"Cinsel istismar suçtur ve bildirilmesi gerekir."}]},"after":{"turkish":"cinsel istismar","note":"Misbruik “istismar” demektir. Seksuele intimidatie için Türkçede “cinsel taciz” kullanılır.","legal":null,"examples":[{"nl":"In de brief staat de term ‘seksueel misbruik’.","tr":"Mektupta “cinsel istismar” ifadesi geçiyor."}]}},{"date":"STAJ","head":"collegebundel","before":{"turkish":"belediye yönetim kurulu paketi / meclis dosyası","note":"Gemeente yönetiminde belediye başkanı ve wethouders'ın (belediye meclis üyeleri) toplantılarına hazırlanan karar ve belge paketi. 'College van B&W' = Burgemeester en Wethouders.","examples":[{"nl":"Het voorstel staat in de collegebundel van volgende week.","tr":"Teklif gelecek haftanın belediye meclis dosyasında yer alıyor."},{"nl":"De collegebundel is openbaar en online in te zien.","tr":"Belediye meclis dosyası kamuya açık ve çevrimiçi görüntülenebilir."},{"nl":"Het besluit is genomen op basis van de stukken in de collegebundel.","tr":"Karar, belediye meclis dosyasındaki belgeler temelinde alındı."}],"uitleg":"Een bundel stukken voor een college of bestuur; controleer welke betekenis hier bedoeld is."},"after":{"turkish":"collegebundel adlı belge veya derleme (bağlam gerekli)","note":"Kastedilen yayını veya toplantıyı kaynak cümleden kontrol et. Tek başına sözcükten belediye meclisi anlamı çıkarılamaz.","examples":[{"nl":"Welke collegebundel bedoel je precies?","tr":"Tam olarak hangi derlemeyi kastediyorsun?"}],"uitleg":"Vraag welke bundel de spreker bedoelt."},"review":true},{"date":"15/06","head":"Daar hebben we een inloopuur voor.","before":{"turkish":"Bunun için walk-in saatimiz var. / Bunun için serbest başvuru saatimiz var.","note":"'Inloopuur' = önceden randevu almadan gidilen serbest danışma saati. ZO! gibi kurumların temel hizmetlerinden biri. 'Inlopen' = randevusuz girmek.","examples":[{"nl":"U hoeft geen afspraak te maken. Daar hebben we inloopuur voor.","tr":"Randevu almanıza gerek yok. Bunun için serbest başvuru saatimiz var."},{"nl":"Het inloopuur is elke dinsdag van 9 tot 12 uur.","tr":"Serbest başvuru saati her salı 9'dan 12'ye kadar."},{"nl":"Voor kleine vragen kunt u terecht tijdens het inloopuur.","tr":"Küçük sorular için serbest başvuru saatimize gelebilirsiniz."}]},"after":{"turkish":"Bunun için randevusuz danışma saatimiz var.","note":"Inloopuur, randevu almadan gelinebilen danışma saatidir.","examples":[{"nl":"Daar hebben we een inloopuur voor. Zal ik kijken wanneer het is?","tr":"Bunun için randevusuz danışma saatimiz var. Ne zaman olduğuna bakayım mı?"}]}},{"date":"15/06","head":"Van Stichting ZO! ben ik!","before":{"dutch":"Van Stichting ZO! ben ik!","turkish":"Ben Stichting ZO!'dan geliyorum! / Stichting ZO! adına ben buradayım.","note":"Kendini temsil ettiğin kurumu tanıtırken kullanılan doğal cümle yapısı. 'Van [kurum] ben ik' = o kurumdan olduğunu vurgulayan giriş. Telefon ve ilk temasta çok kullanılır.","examples":[{"nl":"Goedemiddag, van Stichting ZO! ben ik — mijn naam is Yasin.","tr":"İyi günler, ben Stichting ZO!'dan Yasin."},{"nl":"Van Stichting ZO! ben ik, ik bel namens uw cliënt.","tr":"Ben Stichting ZO!'dan arıyorum, müşteriniz adına."},{"nl":"U spreekt met Stichting ZO! — waarmee kan ik u helpen?","tr":"Stichting ZO! ile görüşüyorsunuz — size nasıl yardımcı olabilirim?"}]},"after":{"dutch":"Ik werk bij Stichting ZO!","turkish":"Stichting ZO!’da çalışıyorum.","note":"İlk görüşmede kurumunu tanıtmak için kullanabilirsin.","examples":[{"nl":"Goedemorgen, ik werk als sociaal raadsman bij Stichting ZO!","tr":"Günaydın, Stichting ZO!’da sosyal ve hukuki konularda danışmanlık yapıyorum."},{"nl":"Goedemiddag, u spreekt met Yasin van Stichting ZO!","tr":"İyi günler, ben Stichting ZO!’dan Yasin."}]}},{"date":"17/06","head":"Zijn we zo duidelijk?","before":{"dutch":"Zijn we zo duidelijk?","turkish":"Bu şekilde anlaşıldık mı? / Bu kadar açık mı?","note":"Bir açıklama yaptıktan sonra anlaşılıp anlaşılmadığını teyit etmek için sorulan kısa soru. 'Is dit duidelijk?' ile benzer ama 'zo' ekiyle az daha gayri resmi.","examples":[{"nl":"U moet de stukken voor vrijdag inleveren. Zijn we zo duidelijk?","tr":"Belgeleri Cuma'dan önce teslim etmeniz gerekiyor. Bu şekilde anlaşıldık mı?"},{"nl":"Zijn we zo duidelijk over de vervolgstappen?","tr":"Sonraki adımlar konusunda bu kadar açık mıyız?"},{"nl":"Ik wil zeker weten: zijn we zo duidelijk?","tr":"Emin olmak istiyorum: bu şekilde anlaşıldık mı?"}]},"after":{"dutch":"Heb ik het zo duidelijk uitgelegd?","turkish":"Böyle anlaşılır açıklayabildim mi?","note":"Açıklamanın anlaşılır olup olmadığını sorar. Kişiye kendi sorusunu sorması için de alan açabilirsin.","examples":[{"nl":"Heb ik het zo duidelijk uitgelegd, of zal ik een voorbeeld geven?","tr":"Böyle anlaşılır açıklayabildim mi, yoksa örnek vereyim mi?"},{"nl":"Welke vragen heeft u nog over de volgende stap?","tr":"Bir sonraki adımla ilgili başka hangi sorularınız var?"}]}},{"date":"STAJ","head":"beoordelen","before":{"examples":[{"nl":"De gemeente beoordeelt de aanvraag binnen acht weken.","tr":"Belediye başvuruyu sekiz hafta içinde değerlendirir."},{"nl":"Wij beoordelen uw situatie op basis van de ingediende stukken.","tr":"Durumunuzu sunulan belgeler temelinde değerlendiriyoruz."},{"nl":"De rechter beoordeelt of er sprake is van onrechtmatige daad.","tr":"Hâkim haksız fiilin söz konusu olup olmadığını değerlendirir."}],"legal":"Türk hukukunda 'değerlendirmek' veya 'takdir etmek'. Bestuursrechtelijk: bestuursorgaan beoordeelt de aanvraag o.b.v. de wet. Marginale toetsing (sınırlı denetim) vs. volledige toetsing (tam denetim) ayrımı önemli."},"after":{"examples":[{"nl":"In de brief staat wie uw aanvraag beoordeelt.","tr":"Mektupta başvurunuzu kimin değerlendireceği yazıyor."},{"nl":"Weet u wanneer mijn aanvraag wordt beoordeeld?","tr":"Başvurumun ne zaman değerlendirileceğini biliyor musunuz?"}],"legal":null}},{"date":"STAJ","head":"immers","before":{"examples":[{"nl":"Hij heeft recht op ondersteuning, hij is immers woonachtig in de gemeente.","tr":"Nitekim belediyede ikamet ettiğinden, desteğe hak kazanmaktadır."},{"nl":"De termijn is verstreken, de bezwaarschrift is immers te laat ingediend.","tr":"Süre dolmuştu; zira itiraz dilekçesi geç sunulmuştu."},{"nl":"U bent immers al klant bij ons.","tr":"Bilindiği üzere zaten bizim müşterimizsiniz."}]},"after":{"examples":[{"nl":"Ik ken de brief. We hebben hem immers gisteren samen gelezen.","tr":"Mektubu biliyorum. Ne de olsa dün birlikte okuduk."},{"nl":"Een nieuwe afspraak is handig. De vorige afspraak ging immers niet door.","tr":"Yeni bir randevu iyi olur. Çünkü önceki randevu gerçekleşmedi."}]}},{"date":"STAJ","head":"verzorgende ouder","before":{"turkish":"bakım veren ebeveyn / çocuğun bakımını üstlenen ebeveyn","note":"Boşanma ve co-ouderschap bağlamında önemli bir terim. 'Verzorgende ouder' = çocuğun ağırlıklı olarak yanında yaşadığı ebeveyn. Alimentatie (nafaka) ve toeslagen açısından belirleyici.","legal":"Türk hukukunda 'velayeti alan ebeveyn' veya 'fiili bakım yükümlüsü'. Hollanda'da co-ouderschap yaygın; verzorgende ouder toeslagen ve alimentatie açısından belirleyici. Belastingdienst Toeslagen bu ayrımı dikkate alır.","examples":[{"nl":"De verzorgende ouder ontvangt de kinderbijslag.","tr":"Bakım veren ebeveyn çocuk yardımını alır."},{"nl":"Na de scheiding is de moeder de verzorgende ouder.","tr":"Boşanmanın ardından anne bakım veren ebeveyn oldu."},{"nl":"De verzorgende ouder heeft recht op kinderopvangtoeslag.","tr":"Bakım veren ebeveynin çocuk bakım yardımına hakkı var."}]},"after":{"turkish":"çocuğun günlük bakımını üstlenen ebeveyn","note":"Burada verzorgend günlük bakımı anlatır.","legal":null,"examples":[{"nl":"In het formulier wordt gevraagd wie de verzorgende ouder is.","tr":"Formda çocuğun günlük bakımını hangi ebeveynin üstlendiği soruluyor."},{"nl":"Hoe heeft u de zorg voor uw kind verdeeld?","tr":"Çocuğunuzun bakımını aranızda nasıl paylaştınız?"}]}},{"date":"STAJ","head":"seksuele intimidatie","before":{"turkish":"cinsel taciz / cinsel yıldırma","note":"'Misbruik'ten fark: intimidatie daha geniş kapsamlı, fiziksel temas olmaksızın da olabilir (sözlü, nonverbaal). İşyerinde ve özel hayatta ayrı hukuki düzenlemeler.","legal":"Türk hukukunda 'cinsel taciz' — TCK md. 105. Hollanda: Arbowet md. 3 (werkgever verplichtingen), WvSr md. 239, 246. Gelijke behandelingswetgeving ook van toepassing.","examples":[{"nl":"Seksuele intimidatie op de werkvloer is verboden.","tr":"İşyerinde cinsel taciz yasaktır."},{"nl":"Ze heeft aangifte gedaan van seksuele intimidatie.","tr":"Cinsel taciz için suç duyurusunda bulundu."},{"nl":"De werkgever is verplicht om seksuele intimidatie te voorkomen.","tr":"İşveren cinsel tacizi önlemek zorundadır."}]},"after":{"turkish":"cinsel taciz","note":"İş yerinde istenmeyen cinsel söz, ilgi veya davranış anlatılırken bu terimi duyabilirsin.","legal":null,"examples":[{"nl":"Ik wil met iemand praten over seksuele intimidatie op mijn werk.","tr":"İş yerinde yaşadığım cinsel taciz hakkında biriyle konuşmak istiyorum."}]}},{"date":"17/06","head":"bemenst","before":{"turkish":"personel ile donatılmış / görevliyle dolu","examples":[{"nl":"Het inloopuur is altijd bemenst door minimaal twee collega's.","tr":"Serbest başvuru saatinde her zaman en az iki meslektaş görevlidir."},{"nl":"De balie is op dit moment niet bemenst.","tr":"Resepsiyon şu anda görevsiz."},{"nl":"We hebben extra collega's nodig om de telefoonlijn goed te bemensen.","tr":"Telefon hattını düzgün şekilde personelle donatmak için ekstra meslektaşa ihtiyacımız var."}]},"after":{"turkish":"görevli bulunan / başında personel olan","examples":[{"nl":"Is de balie vanmiddag bemenst?","tr":"Bugün öğleden sonra danışmada görevli var mı?"},{"nl":"Wie bemenst vandaag de telefoon?","tr":"Bugün telefonlara kim bakıyor?"}]}}];
